#!/usr/bin/env python3
"""test_src_arch_page_r33.py — R33 KATs of the rebuilt source-architecture page artifacts/dero-src-arch.html, generated by
harness/gen_deroarch.py (r33 overhaul: design tokens with a light and a dark theme, a sticky contents column grouped into
parts, plain-language orientation sections, generated SVG diagrams, chartkit charts with text alternatives, repo-relative
citations, the privacy pass pub()).

Each KAT re-reads the page and the records with its OWN parsing (no generator code) and compares.
  SA0 the generator built the page (exit 0) and `gen_deroarch.py check` calls it CURRENT
  SA1 every section is present, in the order of the contents, numbered 1..N, listed in the contents under its part,
      and the sections coherence and the gates bind to (areas, chainobs, peers, press with t-dtrack, live, index) exist
  SA2 every chart has its text alternative (chartkit.audit; >= 15 charts), every diagram SVG in a <figure> has
      role="img" and an accessible name, and chartkit.audit itself fails a forged chart without a <desc>, one whose
      table lacks a row, and a matrix chart without its title
  SA3 the coherence-bound figures equal their records: the Areas scorecard run id and every area state =
      harness/runtime/area_intel.json; the disclosure track table (latest round, verdict, state) =
      harness/loop/disclosure_track.json; the chain / peer observatory capture times and OBSERVED / ANOMALY counts =
      consensus_intel.json / peer_intel.json; the stamp's byte count and fingerprint = the page; the overview charts
      (area states, chain grades, peer grades, disclosure verdicts) = the same records; and harness/intel/coherence.py
      reports no drift on this page
  SA4 no private value: no local absolute path (/Users, /home, /private/tmp|var), no home-relative path, no DERO address,
      no LAN or non-code IPv4, no machine-model name, no agent-tool path; the citation registry has no home directory
      and every file citation is repo-relative
  SA5 the page names the current round (harness/round.json) in its <title> and in its kicker
  SA6 the look-and-feel contract: the same token set in :root (light), under prefers-color-scheme guarded by
      :root:not([data-theme="light"]) and under :root[data-theme="dark"]; a theme button; :focus-visible; reduced motion;
      the 900px breakpoint and <details id="tocd"> that print_copy relies on; no external script, style, font or image
  SA7 the orientation figures equal the model: the layer diagram names every package with its line count, the
      lines-per-package chart = the inventory rows, the evidence-class chart = the anchors of model/verified.json per
      class, and every glossary value = its constant row (the integrator address withheld)
  SA8 every file citation of the registry opens the line it names: the file exists and its line holds the quote
      (placeholders such as [home] split the comparison; pseudonymised peers compared masked)
Mutations (katmut classify: each names the KAT that owns its defect) build the page in a scratch tree (harness, .skills
copied; artifacts, harness/runtime and the source tree linked read-only) and run the KATs in a fresh interpreter.

  python3 -I harness/kat/test_src_arch_page_r33.py            # KATs, then the mutations; exit 0 · 3 a KAT failed · 4 a mutation missed
  python3 -I harness/kat/test_src_arch_page_r33.py --no-mutations
"""
import collections, contextlib, html, importlib.util, io, json, os, re, shutil, subprocess, sys, tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent.parent
PAGE = 'artifacts/dero-src-arch.html'
GEN = 'harness/gen_deroarch.py'
PATHS = {'gen': GEN, 'chart': 'harness/kit/chartkit.py'}
SECTIONS = ['start', 'tour', 'lifecycle', 'glossary', 'map', 'consensus', 'flows', 'deps', 'local', 'evolution', 'live', 'intel',
            'bridge', 'triage', 'findings', 'coverage', 'press', 'areas', 'chainobs', 'peers', 'harness', 'method', 'quarantine', 'index']
BOUND = ['areas', 'chainobs', 'peers', 'press', 'live', 'index']
PLACE = re.compile(r'\[(?:home|datadir|repo|scratch|tool-dir|project|address|e-mail|lan-ip)\]|\bmy-node\b|\bhost\b|\blaptop\b|\buser\b')


def R(over):
    return Path(over.get('root') or ROOT)


def page(over):
    return (R(over) / PAGE).read_text(encoding='utf-8')


def js(root, rel):
    return json.loads((Path(root) / rel).read_text())


def plain(s):
    s = re.sub(r'<span class="ct [^"]*"[^>]*>[^<]*</span>', '', s)
    s = re.sub(r'<span class="tt-i"[^>]*>.*?</span>', '', s)
    return re.sub(r'\s+', ' ', html.unescape(re.sub(r'<[^>]+>', ' ', s))).strip()


def table_rows(h, tid):
    m = re.search(r'<table id="' + re.escape(tid) + r'"[^>]*>(.*?)</table>', h, re.S)
    if not m:
        return None
    b = re.search(r'<tbody>(.*?)</tbody>', m.group(1), re.S)
    return [[plain(c) for c in re.findall(r'<td[^>]*>(.*?)</td>', tr, re.S)] for tr in re.findall(r'<tr[^>]*>(.*?)</tr>', b.group(1) if b else '', re.S)]


def chart_table(h, cid):
    """{category: [values…]} of a chart's data table (numbers parsed)."""
    rows = table_rows(h, cid + '-tbl')
    if rows is None:
        return None
    return {r[0]: [float(x.replace(',', '')) for x in r[1:]] for r in rows if r}


def section(h, sid):
    a = h.find(f'<section id="{sid}"')
    return h[a:h.find('</section>', a)] if a >= 0 else ''


def load_mod(name, rel, root):
    spec = importlib.util.spec_from_file_location(name, Path(root) / rel)
    m = importlib.util.module_from_spec(spec)
    sys.path.insert(0, str(Path(root) / 'harness/kit'))
    try:
        spec.loader.exec_module(m)
    finally:
        sys.path.pop(0)
    return m


# ───────────────────────────── the KATs ─────────────────────────────
def sa0(over):
    rc = over.get('gen_rc', 0)
    r = subprocess.run([sys.executable, '-I', str(R(over) / GEN), 'check'], capture_output=True, text=True, timeout=600)
    return rc == 0 and r.returncode == 0 and 'CURRENT' in r.stdout, f'build rc {rc}; check rc {r.returncode}: {r.stdout.strip()[:120]}'


def sa1(over):
    h = page(over)
    got = re.findall(r'<section id="([\w-]+)"><h2><span class="sn">(\d+)</span>', h)
    ids = [i for i, _ in got]
    nums = [int(n) for _, n in got]
    nav = re.search(r'<nav class="toc"[^>]*>(.*?)</nav>', h, re.S)
    toc = re.findall(r'<a href="#([\w-]+)"><span class="sn">(\d+)</span>', nav.group(1) if nav else '')
    parts = re.findall(r'<li class="part">', nav.group(1) if nav else '')
    want = [s for s in SECTIONS if s in ids]
    ok = (ids == SECTIONS and nums == list(range(1, len(ids) + 1)) and [(i, str(n)) for i, n in zip(ids, nums)] == toc
          and len(parts) >= 6 and all(b in ids for b in BOUND) and 'id="t-dtrack"' in section(h, 'press')
          and 'id="sx-q"' in section(h, 'index'))
    return ok, f'sections {ids}; want {SECTIONS}; numbered {nums[:3]}..; toc {len(toc)}; parts {len(parts)}; missing {[s for s in SECTIONS if s not in want]}'


def _chk(root):
    return load_mod('chartkit_sa33', 'harness/kit/chartkit.py', root)


def sa2(over):
    h = page(over)
    chk = _chk(R(over))
    a = chk.audit(h)
    bad_svg = []
    for f in re.findall(r'<figure[^>]*>(.*?)</figure>', h, re.S):
        for attrs in re.findall(r'<svg\b([^>]*)>', f):
            if 'role="img"' not in attrs or not re.search(r'aria-label(?:ledby)?="[^"]+"', attrs):
                bad_svg.append(attrs[:80])
    forged = chk.bar_chart('x', 'T', 'D', ['a', 'b'], [1, 2])
    no_desc = re.sub(r'<desc id="x-d">[^<]*</desc>', '<desc id="x-d"></desc>', forged)
    short = forged.replace('<tr><td>b</td><td>2</td></tr>', '', 1)
    mt = chk.matrix_chart('m', 'M', 'D', ['r1', 'r2'], ['c1'], [[1], [2]])
    mt_bad = re.sub(r'<title id="m-t">[^<]*</title>', '<title id="m-t"></title>', mt)
    self_ok = chk.audit(forged)['ok'] and not chk.audit(no_desc)['ok'] and not chk.audit(short)['ok'] and chk.audit(mt)['ok'] and not chk.audit(mt_bad)['ok']
    return (a['ok'] and a['charts'] >= 15 and not bad_svg and self_ok,
            f"{a['charts']} charts, {len(a['bad'])} bad {a['bad'][:2]}; diagram svgs without a name {len(bad_svg)} {bad_svg[:2]}; audit self-test {self_ok}")


def sa3(over):
    root, h = R(over), page(over)
    probs = []
    ai = js(root, 'harness/runtime/area_intel.json')
    st = {a['id']: a.get('state') for a in ai.get('areas', [])}
    ttl = {a.get('title'): a.get('state') for a in ai.get('areas', [])}
    sa = section(h, 'areas')
    m = re.search(r'Scorecard run (\d{8}T\d{6})', plain(sa))
    if not m or m.group(1) != ai.get('run_id'):
        probs.append(f"scorecard run {m.group(1) if m else None} != {ai.get('run_id')}")
    for r in table_rows(sa, 't-areas') or []:
        if r and r[0] in ttl and r[1] != ttl[r[0]]:
            probs.append(f'area {r[0]} {r[1]} != {ttl[r[0]]}')
    ca = chart_table(h, 'ch-area-states') or {}
    want = collections.Counter(st.values())
    if {k: int(v[0]) for k, v in ca.items()} != dict(want):
        probs.append(f'area chart {ca} != {dict(want)}')
    tr = js(root, 'harness/loop/disclosure_track.json')
    lat = {c['id']: c['history'][-1] for c in tr.get('claims', []) if c.get('history')}
    seen = 0
    for r in table_rows(h, 't-dtrack') or []:
        mm = re.match(r'([A-Z][\w-]*?)\s+—', r[0] if r else '')
        if not mm or mm.group(1) not in lat:
            continue
        seen += 1
        L = lat[mm.group(1)]
        pairs = re.findall(r'\b(R\d+[a-z]?) ([a-z][a-z -]*?)(?= R\d+[a-z]? | now:|$)', r[1])
        sm = re.search(r'now: (\S+)', r[1])
        if not pairs or pairs[-1][0] != L['round'] or re.sub(r'[\s_]+', '-', pairs[-1][1].strip()).upper() != L['verdict'] \
                or not sm or sm.group(1) != L.get('state'):
            probs.append(f"{mm.group(1)} {pairs[-1] if pairs else None} now {sm.group(1) if sm else None} != {L['round']} {L['verdict']} {L.get('state')}")
    if seen < len(lat):
        probs.append(f'disclosure track rows {seen} < claims {len(lat)}')
    cs = [lat[f'C{i}']['verdict'] for i in range(1, 9) if f'C{i}' in lat]
    cd = chart_table(h, 'ch-disclosure') or {}
    wd = {'confirmed': cs.count('CONFIRMED'), 'partly confirmed': cs.count('PARTLY-CONFIRMED'), 'refuted': cs.count('REFUTED'),
          'not decidable': cs.count('CANNOT-DETERMINE-LOCALLY')}
    if {k: int(v[0]) for k, v in cd.items()} != wd:
        probs.append(f'disclosure chart {cd} != {wd}')
    for sid, rec, grades in (('chainobs', 'harness/runtime/consensus_intel.json', lambda d: d.get('summary') or {}),
                             ('peers', 'harness/runtime/peer_intel.json',
                              lambda d: {'OBSERVED': (d.get('kpis') or {}).get('observed'), 'ANOMALY': (d.get('kpis') or {}).get('anomaly')})):
        d = js(root, rec)
        seg = plain(section(h, sid))
        cm = re.search(r'Capture (\S+?)[,. ]', seg)
        if not cm or cm.group(1) != str(d.get('captured')):
            probs.append(f"{sid} capture {cm.group(1) if cm else None} != {d.get('captured')}")
        g = grades(d)
        for k in ('OBSERVED', 'ANOMALY'):
            gm = re.search(rf'(\d+) detectors {k}', seg)
            if not gm or g.get(k) is None or int(gm.group(1)) != int(g[k]):
                probs.append(f'{sid} {k} {gm.group(1) if gm else None} != {g.get(k)}')
        ch = chart_table(h, 'ch-chain-grades' if sid == 'chainobs' else 'ch-peer-grades') or {}
        for k, v in ch.items():
            if g.get(k) is None or int(v[0]) != int(g[k]):
                probs.append(f'{sid} chart {k} {v[0]} != {g.get(k)}')
        if not ch:
            probs.append(f'{sid}: no overview chart')
    stp = js(root, 'harness/stamp.json')
    if stp.get('bytes') != (root / PAGE).stat().st_size or f"<code>{stp.get('fingerprint')}</code>" not in h:
        probs.append(f"stamp bytes {stp.get('bytes')} / page {(root / PAGE).stat().st_size}; fingerprint {stp.get('fingerprint')}")
    r = subprocess.run([sys.executable, '-I', str(root / 'harness/intel/coherence.py'), '--root', str(root), '--json'],
                       capture_output=True, text=True, timeout=600)
    try:
        dr = [x for x in json.loads(r.stdout)['drifts'] if x.get('file') == PAGE]
    except (ValueError, KeyError):
        dr = [f'coherence rc {r.returncode}: {(r.stdout + r.stderr)[-160:]}']
    if dr:
        probs.append(f'coherence drifts on the page: {str(dr)[:200]}')
    return not probs, f'{len(probs)} disagreement(s): {probs[:4]}'


sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'kit'))   # r33: privkit.private_terms (names kept outside the repo)
PRIV = [('a local absolute path', re.compile(r'/Users/|/home/[a-z]\w*/|/private/(?:tmp|var)/')),
        ('a home-relative path', re.compile(r'(?<![\w/.~-])~/[A-Za-z0-9._-]')),
        ('a DERO address (or a quoted prefix of one)', re.compile(r'\b(?:dero|deto)(?:1|i)[0-9a-z]{4,}\b')),
        ('a machine-model name', re.compile(r'(?i)\bMac[- ]?Studio\b|\bMacBook\b|\bM[1-9][- ]?(?:Ultra|Max|Pro)\b')),
        ('an agent-tool path', re.compile(r'\.claude/|-Users-[A-Za-z0-9]+-')),
        *[(f'a private name ({ph})', rx) for rx, ph in __import__('privkit').private_terms()],
        ('a LAN address', re.compile(r'(?<![\d.])(?:10\.\d{1,3}|172\.(?:1[6-9]|2\d|3[01])|192\.168)(?:\.\d{1,3}){2}(?![\d\w]|\.\d)'))]


def sa4(over):
    root, h = R(over), page(over)
    hits = [f'{w} ({len(rx.findall(h))}: {rx.search(h).group(0)!r})' for w, rx in PRIV if rx.search(h)]
    m = re.search(r'<script type="application/json" id="ak-cites">(.*?)</script>', h, re.S)
    reg = json.loads(m.group(1).replace('<\\/', '</')) if m else {}
    if reg.get('H'):
        hits.append('the citation registry names a home directory')
    files = [reg['S'][x[1]] for e in reg.get('R', []) for x in e[3] if x[0] == 'f']
    absf = [p for p in files if not p.startswith('/') or (root.parts[1] and p.startswith('/' + root.parts[1] + '/'))]
    if absf or not files:
        hits.append(f'{len(absf)} file citation(s) not repo-relative, e.g. {absf[:1]}')
    pk = load_mod('privkit_sa33', 'harness/kit/privkit.py', root)
    leaks = pk.page_ip_leaks(h, pk.code_literal_ips(root))
    if leaks:
        hits.append(f'{len(leaks)} non-reserved IPv4 literal(s) no .go file holds')
    return not hits, f'{len(files)} file citations; problems: {hits[:4]}'


def sa5(over):
    h = page(over)
    cur = json.loads((R(over) / 'harness/round.json').read_text()).get('current', '')
    mm = re.fullmatch(r'r(\d+)([a-z]?)', cur)
    name = f'Round {mm.group(1)}{mm.group(2)}' if mm else cur
    t = re.search(r'<title>(.*?)</title>', h)
    k = re.search(r'<div class="kicker">(.*?)</div>', h, re.S)
    ok = bool(name) and t and name in t.group(1) and k and name in plain(k.group(1))
    return ok, f'round {cur} -> {name!r}; title {t.group(1) if t else None!r}; kicker has it {bool(k and name in plain(k.group(1)))}'


def tokens(block):
    return set(re.findall(r'--([\w-]+)\s*:', block))


def sa6(over):
    h = page(over)
    st = ''.join(re.findall(r'<style[^>]*>(.*?)</style>', h, re.S))
    light = re.search(r':root\{(.*?)\}', st, re.S)
    dark_mq = re.search(r'@media \(prefers-color-scheme: dark\)\{:root:not\(\[data-theme="light"\]\)\{(.*?)\}\}', st, re.S)
    dark_at = re.search(r':root\[data-theme="dark"\]\{(.*?)\}', st, re.S)
    probs = []
    if not (light and dark_mq and dark_at):
        probs.append('a theme block is missing or unguarded')
    else:
        L, D1, D2 = tokens(light.group(1)), tokens(dark_mq.group(1)), tokens(dark_at.group(1))
        colour = {t for t in L if re.search(r'--' + re.escape(t) + r'\s*:\s*#', light.group(1))}
        if not colour or not colour <= D1 or D1 != D2:
            probs.append(f'dark themes lack {sorted(colour - D1)[:4]} / differ {sorted(D1 ^ D2)[:4]}')
    for need in ('id="themebtn"', ':focus-visible', 'prefers-reduced-motion', '@media (max-width:900px){', 'id="tocd">',
                 'body{margin:0;background:var(--bg)', 'nav class="toc"'):
        if need not in h:
            probs.append(f'missing {need}')
    ext = re.findall(r'<(?:script|img|link)\b[^>]*\b(?:src|href)="(?:https?:)?//[^"]*"', h) + re.findall(r'@import|url\(\s*["\']?https?:', st)
    if ext:
        probs.append(f'{len(ext)} external resource(s)')
    return not probs, f'problems {probs}'


def sa7(over):
    root, h = R(over), page(over)
    V = js(root, 'harness/model/verified.json')
    pk = [r for r in V if r.get('section') == 'packages']
    probs = []
    d = re.search(r'<desc id="tier-d">(.*?)</desc>', h, re.S)
    dd = html.unescape(d.group(1)) if d else ''
    for p in pk:
        if f"{p['pkg']} ({p['loc']:,} lines)" not in dd:
            probs.append(f"layer diagram lacks {p['pkg']} {p['loc']}")
    loc = chart_table(h, 'ch-pkg-loc') or {}
    if {k: int(v[0]) for k, v in loc.items()} != {p['pkg']: p['loc'] for p in pk}:
        probs.append(f'lines chart {list(loc.items())[:3]} != inventory')
    cnt = collections.Counter(e['kind'] for r in V for e in r['evidence'])
    cc = chart_table(h, 'ch-classes') or {}
    if not cc or {k: int(v[0]) for k, v in cc.items()} != {k: v for k, v in cnt.items() if k in cc} or set(cnt) - set(cc):
        probs.append(f'class chart {cc} != {dict(cnt)}')
    cr = {r['title']: r for r in V if r.get('id', '').startswith('const-')}
    gl = table_rows(h, 't-gloss') or []
    n = 0
    for r in gl:
        m = re.match(r'(.*?) \((.*)\)$', r[2]) if len(r) > 2 else None
        if not m or m.group(2) not in cr:
            continue
        n += 1
        row = cr[m.group(2)]
        want = 'withheld' if row['id'] == 'const-dev' else re.sub(r'\s+', ' ', str(row.get('value'))).strip()
        if m.group(1).strip() != want:
            probs.append(f"glossary {m.group(2)} {m.group(1)[:40]!r} != {want[:40]!r}")
    if n < 10:
        probs.append(f'only {n} glossary constants found')
    return not probs, f'{len(pk)} packages, {n} glossary constants; problems {probs[:4]}'


def sa8(over):
    root, h = R(over), page(over)
    m = re.search(r'<script type="application/json" id="ak-cites">(.*?)</script>', h, re.S)
    reg = json.loads(m.group(1).replace('<\\/', '</')) if m else {'S': [], 'R': []}
    S = reg['S']
    pk = load_mod('privkit_sa33b', 'harness/kit/privkit.py', root)
    norm = lambda s: re.sub(r'\s+', ' ', str(s).translate(str.maketrans({'‘': "'", '’': "'", '“': '"', '”': '"', '–': '-', '—': '-', '…': '...'}))).strip()
    cache, bad, n = {}, [], 0
    for e in reg.get('R', []):
        for x in e[3]:
            if x[0] != 'f':
                continue
            p, ln, q = S[x[1]], x[2], S[x[3]]
            if q.startswith('(binary file') or not ln:
                continue
            n += 1
            f = root / p.lstrip('/')
            if f not in cache:
                try:
                    cache[f] = f.read_text(errors='replace').splitlines()
                except OSError:
                    cache[f] = None
            ls = cache[f]
            if ls is None or ln > len(ls):
                bad.append(f'{p}:{ln} (no such line)')
                continue
            line = norm(ls[ln - 1])
            frags = [norm(s) for s in PLACE.split(q)]
            frags = [s for s in frags if len(s) >= 4]
            if not all(s in line or pk.mask(s) in pk.mask(line) for s in frags):
                bad.append(f'{p}:{ln}')
    return not bad and n > 1000, f'{n} file citations checked, {len(bad)} do not hold their quote: {bad[:3]}'


KATS = [('SA0', sa0), ('SA1', sa1), ('SA2', sa2), ('SA3', sa3), ('SA4', sa4), ('SA5', sa5), ('SA6', sa6), ('SA7', sa7), ('SA8', sa8)]
OWNERS = {f'r33 {k}': [k] for k, _ in KATS}

MUTATIONS = [
    ('gen', [("    A(H('glossary', 'Glossary',", "    A(H('glossary-x', 'Glossary',")], 'r33 SA1: a section leaves the contents order'),
    ('chart', [('<desc id="{cid}-d">{E(_desc(desc, cats, vals, unit, fmt))}</desc>', '<desc id="{cid}-d"></desc>')],
     'r33 SA2: a bar chart loses its text alternative'),
    ('chart', [("        body.append(f'<tr><td>{E(r)}", "        body.append('') if i == n - 1 else body.append(f'<tr><td>{E(r)}")],
     'r33 SA2: a matrix chart table drops its last row'),
    ('gen', [("    ast = collections.Counter(r['state'] for r in ar)", "    ast = collections.Counter(r['state'] for r in ar[1:] + ar[:1] if r is not ar[0])")],
     'r33 SA3: the area-state chart drops an area'),
    ('gen', [("pg = [('OBSERVED', pk2.get('observed')), ('ANOMALY', pk2.get('anomaly'))]", "pg = [('OBSERVED', pk2.get('anomaly')), ('ANOMALY', pk2.get('observed') + 1)]")],
     'r33 SA3: the peer-grade chart swaps its counts'),
    ('gen', [("    cites['H'] = ''                     # r33", "    cites['H'] = str(Path.home())       # r33")], 'r33 SA4: the registry names the home directory'),
    ('gen', [("    return pub(page)\n", "    return page\n")], 'r33 SA4: the privacy pass is skipped'),
    ('gen', [("f'<title>DERO HE Source Architecture ({E(cur_name)})</title>'", "'<title>DERO HE Source Architecture</title>'")],
     'r33 SA5: the title does not name the round'),
    ('gen', [("@media (prefers-color-scheme: dark){{:root:not([data-theme=\"light\"]){{", "@media (prefers-color-scheme: dark){{:root{{")],
     'r33 SA6: the dark theme overrides the light choice'),
    ('gen', [("        'queued': '#a292ec', 'flow': '#e9a25a', 'code-bg': '#12171b',", "        'queued': '#a292ec', 'code-bg': '#12171b',")],
     'r33 SA6: a token has no dark value'),
    ('gen', [("pkgs, [p['pkg'] for p in pkgs], [p['loc'] for p in pkgs], unit='lines'", "pkgs, [p['pkg'] for p in pkgs], [p['files'] for p in pkgs], unit='lines'")],
     'r33 SA7: the lines chart draws file counts'),
    ('gen', [("rows, [k for k, _ in kk], [cnt[k] for k, _ in kk], unit='anchors'", "rows, [k for k, _ in kk], [cnt[k] + 1 for k, _ in kk], unit='anchors'")],
     'r33 SA7: the evidence-class chart is off by one'),
    ('gen', [("val = 'withheld' if cid == 'const-dev' else r.get('value')", "val = 'withheld' if cid == 'const-dev' else r.get('role')")],
     'r33 SA7: a glossary value is not its constant'),
    ('gen', [("out.append(ak.cite_file('/' + rel(e['abs']).lstrip('/'), e.get('line'),", "out.append(ak.cite_file('/' + rel(e['abs']).lstrip('/'), (e.get('line') or 0) + 1,")],
     'r33 SA8: a citation names the line after its anchor'),
]


def katmut():
    spec = importlib.util.spec_from_file_location('katmut_sa33', ROOT / 'harness/kit/katmut.py')
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def run_kats(over):
    res = []
    for name, fn in KATS:
        try:
            with contextlib.redirect_stdout(io.StringIO()):
                ok, *det = fn(over)
        except (Exception, SystemExit) as e:                      # noqa: BLE001 — a crash is a failure
            ok, det = False, [f'{type(e).__name__}: {e}']
        res.append((name, bool(ok), str(det)))
    return res


def workspace(d):
    """a scratch tree: harness/ and .skills/ copied (the build writes model/, loop/, corpus/, stamp.json and the skill's AUTO
    block); harness/runtime/, every artifact but the page and every other top-level entry linked (read only)."""
    d = Path(d)
    for p in ROOT.iterdir():
        if p.name in ('harness', 'artifacts', '.skills'):
            continue
        os.symlink(p, d / p.name)
    shutil.copytree(ROOT / '.skills', d / '.skills', symlinks=True)
    shutil.copytree(ROOT / 'harness', d / 'harness', symlinks=True,
                    ignore=lambda dirp, names: [n for n in names if n in ('__pycache__', '.cache') or (Path(dirp) == ROOT / 'harness' and n == 'runtime')])
    os.symlink(ROOT / 'harness/runtime', d / 'harness/runtime')
    (d / 'artifacts').mkdir()
    for p in (ROOT / 'artifacts').iterdir():
        if p.name != 'dero-src-arch.html':
            os.symlink(p, d / 'artifacts' / p.name)


def main(argv):
    if {'-h', '--help'} & set(argv):
        print(__doc__)
        return 0
    if argv[:1] == ['--kats-json']:                                # one mutant's run, in a fresh interpreter
        print(json.dumps([n for n, ok, _ in run_kats({'root': argv[1], 'gen_rc': int(argv[2])}) if not ok]))
        return 0
    res = run_kats({})
    for name, ok, det in res:
        print(f"{'ok  ' if ok else 'FAIL'} {name} {det[:400]}")
    if not all(ok for _, ok, _ in res):
        print(f'\nr33 src-arch page KATs: {sum(o for _, o, _ in res)}/{len(KATS)} ok · mutations not run (a KAT failed)')
        return 3
    if '--no-mutations' in argv:
        print(f'\nr33 src-arch page KATs: {len(KATS)}/{len(KATS)} ok · mutations not run (--no-mutations)')
        return 0
    K = katmut()
    missed = coupled = 0
    for key, edits, why in MUTATIONS:
        text = (ROOT / PATHS[key]).read_text(encoding='utf-8')
        bad = [f for f, _ in edits if text.count(f) != 1]
        if bad:
            print(f'  ??        {why}: find text occurs {[text.count(f) for f in bad]} times')
            missed += 1
            continue
        for f, r in edits:
            text = text.replace(f, r, 1)
        with tempfile.TemporaryDirectory(prefix='sa33-mut-') as d:
            workspace(d)
            (Path(d) / PATHS[key]).write_text(text, encoding='utf-8')
            g = subprocess.run([sys.executable, '-I', str(Path(d) / GEN), 'build'], capture_output=True, text=True, timeout=900, cwd=d)
            p = subprocess.run([sys.executable, '-I', __file__, '--kats-json', d, str(g.returncode)], capture_output=True, text=True, timeout=900)
            try:
                failed = json.loads(p.stdout.strip().splitlines()[-1])
            except (ValueError, IndexError):
                failed = [n for n, _ in KATS]
        verdict, cpl = K.classify(failed, OWNERS.get(K.defect_of(why), []))
        print(f'  {verdict:<9} {why}' + (f'  [{",".join(failed)}]' if failed else ''))
        missed += verdict != 'proved'
        coupled += bool(cpl)
    print('\n' + K.summary('r33 src-arch page KATs', len(KATS), len(MUTATIONS), missed, coupled))
    return 4 if missed else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
